import{_ as e,o,c as n,l as s,t as a,N as r}from"./chunks/framework.Bbd9fWQx.js";const T=JSON.parse('{"title":"ip-monitor | x-cmd man (ip man8) | state monitoring","titleTemplate":false,"description":"x-cmd man (ip man8 Manual Page) | ip-monitor - state monitoring","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"ip-monitor | x-cmd man (ip man8) | state monitoring"}],["meta",{"name":"og:description","content":"x-cmd man (ip man8 Manual Page) | ip-monitor - state monitoring"}]]},"headers":[],"params":{"isMan":true,"man":"ip-monitor","category":"ip man8","desc":"state monitoring"},"relativePath":"ip/man8/ip-monitor.md","filePath":"ip/man8/ip-monitor.md"}'),i={name:"ip/man8/ip-monitor.md"},l={class:"visually-hidden"},g=r('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>ip-monitor, rtmon - state monitoring</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>ip monitor</strong> [ <strong>all</strong> | <em>OBJECT-LIST</em> ] [ <strong>file</strong> * FILENAME * ] [ <strong>label</strong> ] [ <strong>all-nsid</strong> ] [ <strong>dev</strong> * DEVICE * ]</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><dl><dt><strong>-t</strong>,** -timestamp**</dt><dd>Prints timestamp before the event message on the separated line in format: Timestamp: &lt;Day&gt; &lt;Month&gt; &lt;DD&gt; &lt;hh:mm:ss&gt; &lt;YYYY&gt; &lt;usecs&gt; usec &lt;EVENT&gt;</dd><dt><strong>-ts</strong>,** -tshort**</dt><dd>Prints short timestamp before the event message on the same line in format: [&lt;YYYY&gt;-&lt;MM&gt;-&lt;DD&gt;T&lt;hh:mm:ss&gt;.&lt;ms&gt;] &lt;EVENT&gt;</dd></dl><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The <strong>ip</strong> utility can monitor the state of devices, addresses and routes continuously. This option has a slightly different format. Namely, the <strong>monitor</strong> command is the first in the command line and then the object list follows:</p><p><strong>ip monitor</strong> [ <strong>all</strong> | <em>OBJECT-LIST</em> ] [ <strong>file</strong> * FILENAME * ] [ <strong>label</strong> ] [ <strong>all-nsid</strong> ] [ <strong>dev</strong> * DEVICE * ]</p><p><em>OBJECT-LIST</em> is the list of object types that we want to monitor. It may contain <strong>link</strong>, <strong>address</strong>, <strong>route</strong>, <strong>mroute</strong>, <strong>prefix</strong>, <strong>neigh</strong>, <strong>netconf</strong>, <strong>rule</strong>, <strong>stats</strong>, <strong>nsid</strong> and <strong>nexthop</strong>. If no <strong>file</strong> argument is given, <strong>ip</strong> opens RTNETLINK, listens on it and dumps state changes in the format described in previous sections.</p><p>If the <strong>label</strong> option is set, a prefix is displayed before each message to show the family of the message. For example:</p><p>[NEIGH]10.16.0.112 dev eth0 lladdr 00:04:23:df:2f:d0 REACHABLE [LINK]3: eth1: &lt;BROADCAST,MULTICAST&gt; mtu 1500 qdisc pfifo_fast state DOWN group default link/ether 52:54:00:12:34:57 brd ff:ff:ff:ff:ff:ff</p><p>If the <strong>all-nsid</strong> option is set, the program listens to all network namespaces that have a nsid assigned into the network namespace were the program is running. A prefix is displayed to show the network namespace where the message originates. Example:</p><p>[nsid 0]10.16.0.112 dev eth0 lladdr 00:04:23:df:2f:d0 REACHABLE</p><p>If the <strong>file</strong> option is given, the program does not listen on RTNETLINK, but opens the given file, and dumps its contents. The file should contain RTNETLINK messages saved in binary format. Such a file can be generated with the <strong>rtmon</strong> utility. This utility has a command line syntax similar to <strong>ip monitor</strong>. Ideally, <strong>rtmon</strong> should be started before the first network configuration command is issued. F.e. if you insert:</p><p>rtmon file /var/log/rtmon.log</p><p>in a startup script, you will be able to view the full history later.</p><p>Nevertheless, it is possible to start <strong>rtmon</strong> at any time. It prepends the history with the state snapshot dumped at the moment of starting.</p><p>If the <strong>dev</strong> option is given, the program prints only events related to this device.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><br> <strong>ip</strong>(8)</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Original Manpage by Michail Litvak &lt;mci@owl.openwall.com&gt; <br> Manpage revised by Nicolas Dichtel &lt;nicolas.dichtel@6wind.com&gt;</p>',23);function m(t,p,d,h,c,f){return o(),n("div",null,[s("h1",l,a(t.$params.man),1),g])}const b=e(i,[["render",m]]);export{T as __pageData,b as default};
